// GET /api/search-joue — recherche dossards Joué depuis Redis
app.get('/api/search-joue', async (req, res) => {
  try {
    const { q, type } = req.query;
    if (!q || q.trim().length < 2)
      return res.status(400).json({ error: 'Au moins 2 caractères requis.' });

    const raw = await redisGet('defi_enfance_dossards_joue');
    if (!raw) return res.json({ results: [], count: 0, query: q });

    const coureurs = JSON.parse(raw);
    const term = q.trim().toLowerCase();
    let results = [];

    if (type === 'equipe') {
      results = coureurs
        .filter(c => c.equipe && c.equipe.toLowerCase() === term)
        .sort((a, b) => a.prenom.localeCompare(b.prenom, 'fr'));
    } else {
      results = coureurs
        .filter(c => c.nom.toLowerCase().includes(term) || c.prenom.toLowerCase().includes(term))
        .sort((a, b) => a.nom.localeCompare(b.nom, 'fr'));
    }

    res.json({ results, count: results.length, query: q.trim() });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// GET /api/equipes-joue — liste des équipes Joué
app.get('/api/equipes-joue', async (req, res) => {
  try {
    const raw = await redisGet('defi_enfance_dossards_joue');
    if (!raw) return res.json({ equipes: [] });
    const coureurs = JSON.parse(raw);
    const equipes = [...new Set(coureurs.map(c => c.equipe).filter(Boolean))].sort((a, b) => a.localeCompare(b, 'fr'));
    res.json({ equipes });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});


