app.get('/api/resultats-joue/seed', async (req, res) => {
  try {
    await saveToRedis_key('defi_enfance_resultats_joue', JSON.stringify(RESULTATS_JOUE), 30 * 24 * 60 * 60);
    res.json({ success: true, coureurs: RESULTATS_JOUE.coureurs.length, equipes: RESULTATS_JOUE.equipes.length });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

app.get('/api/resultats-joue', async (req, res) => {
  try {
    const raw = await redisGet('defi_enfance_resultats_joue');
    if (raw) return res.json(JSON.parse(raw));
    // Fallback sur les données en dur
    await saveToRedis_key('defi_enfance_resultats_joue', JSON.stringify(RESULTATS_JOUE), 30 * 24 * 60 * 60);
    res.json(RESULTATS_JOUE);
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

app.listen(PORT, async () => {
  console.log(`Défi Enfance API démarrée sur le port ${PORT}`);
  // Auto-refresh résultats si Redis vide
  try {
    const raw = await redisGet('defi_enfance_resultats');
    if (!raw) {
      console.log('Redis résultats vide — rechargement automatique...');
      const data = await loadResultats();
      await saveToRedis_key('defi_enfance_resultats', JSON.stringify(data), 7 * 24 * 60 * 60);
    } else {
      console.log('Résultats déjà en cache Redis.');
    }
  } catch(e) {
    console.log('Auto-refresh résultats erreur:', e.message);
  }
});
